// Serves the profile stat cards through Cloudflare's edge.
//
// The cards themselves are still generated by scripts/generate_stats.py and
// committed to this repo; this worker only caches them. If GitHub is
// unreachable it falls back to the last copy in the edge cache, so a card
// that was fetched once keeps serving.

const REPO = "LucdeMarillacStJulien/LucdeMarillacStJulien";

// Seconds a card is held at the edge and by GitHub's image proxy. The cards
// themselves change hourly; this only bounds how long an edit takes to show.
const TTL = 300;

// card name -> [branch, path]
const CARDS = {
  "stats.svg": ["main", "assets/stats.svg"],
  "languages.svg": ["main", "assets/languages.svg"],
  "streak.svg": ["main", "assets/streak.svg"],
  "activity.svg": ["main", "assets/activity.svg"],
  "banner.svg": ["main", "assets/banner.svg"],
  "matrix.svg": ["main", "assets/matrix.svg"],
  "snake.svg": ["output", "snake.svg"],
  "snake-dark.svg": ["output", "snake-dark.svg"],
};

export function upstreamFor(pathname) {
  const card = CARDS[pathname.replace(/^\/+/, "")];
  if (!card) return null;
  const [branch, path] = card;
  return `https://raw.githubusercontent.com/${REPO}/${branch}/${path}`;
}

// Profile view counter. Lives here rather than on a third-party badge service
// so it renders at the same speed as the cards and can't vanish.
const BADGE_W = 184;

function badge(count) {
  const n = String(count);
  return `<svg xmlns="http://www.w3.org/2000/svg" width="${BADGE_W}" height="28" role="img" aria-label="Profile views: ${n}">
<title>Profile views: ${n}</title>
<rect width="${BADGE_W}" height="28" rx="4" fill="#1a1b27"/>
<rect width="118" height="28" rx="4" fill="#121F45"/>
<g font-family="'Segoe UI',Ubuntu,'Helvetica Neue',Arial,sans-serif" font-size="12" font-weight="600">
<text x="16" y="18" fill="#a9b1d6">PROFILE VIEWS</text>
<text x="${BADGE_W - 16}" y="18" fill="#FFC906" text-anchor="end">${n}</text>
</g>
</svg>`;
}

async function views(env) {
  if (!env.VIEWS) return badge("-");
  const n = Number((await env.VIEWS.get("count")) || 0) + 1;
  await env.VIEWS.put("count", String(n));
  return badge(n);
}

const svg = (body, age) =>
  new Response(body, {
    headers: {
      "content-type": "image/svg+xml; charset=utf-8",
      "cache-control": `public, max-age=${TTL}`,
      "x-card-age": age,
    },
  });

export default {
  async fetch(request, env) {
    const url = new URL(request.url);

    if (url.pathname === "/views.svg") {
      return new Response(await views(env), {
        headers: {
          "content-type": "image/svg+xml; charset=utf-8",
          // A counter must not be cached, or it shows a stale number.
          "cache-control": "no-cache, no-store, must-revalidate",
        },
      });
    }

    const upstream = upstreamFor(url.pathname);
    if (!upstream) return new Response("Not found", { status: 404 });

    const key = new Request(url.origin + url.pathname, { method: "GET" });
    const cache = caches.default;
    const cached = await cache.match(key);

    try {
      // cacheTtlByStatus, not cacheTtl: a blanket TTL also caches upstream
      // 404s, which pins a card as broken after it is added. The ?h= bucket
      // rolls every TTL, so a stale upstream copy never outlives one bucket.
      const bucket = Math.floor(Date.now() / (TTL * 1000));
      const fresh = await fetch(`${upstream}?h=${bucket}`, {
        cf: { cacheEverything: true, cacheTtlByStatus: { "200-299": TTL, "300-599": 0 } },
      });
      if (!fresh.ok) throw new Error(`upstream ${fresh.status}`);
      const res = svg(await fresh.text(), "fresh");
      await cache.put(key, res.clone());
      return res;
    } catch (err) {
      // ponytail: edge cache is the only fallback; add KV if you need one
      // that survives cache eviction in a cold colo.
      if (cached) return svg(await cached.text(), "stale");
      throw err;
    }
  },
};
